{
  "name": "@makehq/skills",
  "version": "2.0.1",
  "description": "Expert skills for Make automation scenarios, Functions v2 and direct app Endpoint workflows — for Claude Code, Cursor, GitHub Copilot, and other AI agents",
  "license": "MIT",
  "type": "module",
  "author": {
    "name": "Make",
    "email": "support@make.com",
    "url": "https://www.make.com"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/integromat/make-skills.git"
  },
  "homepage": "https://github.com/integromat/make-skills#readme",
  "exports": {
    "./server": "./lib/opencode.js",
    "./skills.json": "./skills.json",
    "./skills/*": "./skills/*",
    "./package.json": "./package.json"
  },
  "files": [
    "lib/",
    "skills/",
    "skills.json"
  ],
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "agent-skills",
    "skills",
    "make",
    "mcp",
    "automation",
    "scenarios",
    "endpoints",
    "integration",
    "workflow",
    "blueprint",
    "no-code",
    "claude-code",
    "cursor",
    "opencode",
    "github-copilot",
    "ai-agents"
  ],
  "scripts": {
    "build": "bash build.sh",
    "version": "node scripts/version.mjs && bash build.sh",
    "version:sync": "node scripts/version.mjs && node scripts/sync-plugins.mjs",
    "check:version": "node scripts/version.mjs --check",
    "check:skills": "node scripts/check-skill-manifests.mjs",
    "check:content": "node scripts/check-skill-content.mjs"
  },
  "agents": {
    "skills": [
      {
        "name": "make-scenario-building",
        "path": "./skills/make-scenario-building"
      },
      {
        "name": "make-scenario-explore",
        "path": "./skills/make-scenario-explore"
      },
      {
        "name": "make-scenario-operations",
        "path": "./skills/make-scenario-operations"
      },
      {
        "name": "make-scenario-reference",
        "path": "./skills/make-scenario-reference"
      },
      {
        "name": "make-endpoints",
        "path": "./skills/make-endpoints"
      },
      {
        "name": "make-functions-v2",
        "path": "./skills/make-functions-v2"
      },
      {
        "name": "make-credential-requests",
        "path": "./skills/make-credential-requests"
      }
    ]
  }
}
